Demo 1 splits horizontally at the middle row. I'll generalize: separator is a column/row that makes the two halves the same size (prefer all-zero separators).

```python
def transform(grid):
    R, C = len(grid), len(grid[0])
    sep_cols = [c for c in range(C) if all(grid[r][c] == 0 for r in range(R))]
    sep_rows = [r for r in range(R) if all(grid[r][c] == 0 for c in range(C))]
    s = None; axis = None
    if len(sep_cols) == 1 and (C - 1) % 2 == 0:
        s, axis = sep_cols[0], 'col'
    elif len(sep_rows) == 1 and (R - 1) % 2 == 0:
        s, axis = sep_rows[0], 'row'
    elif (C - 1) % 2 == 0:
        s, axis = C // 2, 'col'
    else:
        s, axis = R // 2, 'row'
    if axis == 'col':
        A = [row[:s] for row in grid]
        B = [row[s+1:] for row in grid]
    else:
        A = grid[:s]
        B = grid[s+1:]
    from collections import Counter
    ca, cb = Counter(), Counter()
    for row in A: ca.update(row)
    for row in B: cb.update(row)
    common = set(ca) & set(cb) - {0}
    base = max(common, key=lambda v: ca[v] + cb[v])
    out = []
    for i in range(len(A)):
        out.append([3 if A[i][j] == B[i][j] else base for j in range(len(A[0]))])
    return out
